mapper.update:
UPDATE ${tableName}
SET is_read = 1,
    read_at = NOW()
WHERE message_id = #{messageId}
AND receive_user_id = #{receiveUserId}

UPDATE ${tableName}
SET is_read = 1,
    read_at = NOW()
WHERE receive_user_id = #{receiveUserId}
AND conversation_id = #{conversationId}
AND is_read = 0
AND message_id <= #{beforeMessageId}

mapper.select:
SELECT COUNT(*)
FROM ${tableName}
WHERE receive_user_id = #{receiveUserId}
AND conversation_id = #{conversationId}
AND is_read = 0
